tasks.solution:
#include <stdio.h>
int main(void) {
    int values[] = {3, 7, 9};
    int *p = values;
    // 이 주석 아래에 p를 다음 원소로 한 칸 옮기는 줄을 쓰세요.
    // p++는 주소를 원소 하나 크기만큼 옮겨요. 값에 1을 더하는 게 아니에요.
    p++;
    printf("%d\n", *p);
    return 0;
}

