tasks.solution:
#include <stdio.h>
// 이 함수를 고쳐 n이 0이 아니면 n과 sum(n - 1)을 더해 돌려주세요.
// 0이면 멈추고, 아니면 한 단계 작은 sum의 반환값에 n을 더해 돌아와요.
int sum(int n) { return n == 0 ? 0 : n + sum(n - 1); }
int main(void) {
    int count = 3;
    printf("%d\n", sum(count));
    return 0;
}

