tasks.solution:
class Report { int read() { return 3; } }
class Child extends Report {
    static int extra = 9;
    // 이 클래스 안에 상위의 read()를 재정의해 extra를 돌려주는 메서드를 쓰세요.
    // 이름과 매개변수가 같아야 재정의예요. 변수 타입이 Report여도 실제 객체의 read가 실행돼요.
    @Override int read() { return extra; }
}

public class Main {
    public static void main(String[] args) {
        Report report = new Child();
        System.out.println(report.read());
    }
}

