tasks.solution:
-- 안쪽 질의에 HAVING을 더해 수량 합계가 3을 넘는 분류만 남기세요.
-- HAVING은 묶은 뒤의 합계로 그룹을 걸러요. 바깥 질의는 남은 그룹 수를 세요.
SELECT COUNT(*) AS n FROM (
 SELECT category FROM stock
 GROUP BY category HAVING SUM(qty) > 3
) AS totals;
